  fit?: Fit;
  description: string;
};

const args = process.argv.slice(2);
const asJson = args.includes("--json");
const source = args.find((a) => !a.startsWith("--"));

if (args.some((a) => a.startsWith("--") && a !== "--json")) {
  console.error("Usage: npx tsx models.ts [request.json] [--json]");
  process.exit(1);
